@keyframes shimmer {
  0% {
    background-position: 200% 0;
    animation-timing-function: var(--animation--shimmer-burst--easing, var(--easing--ease-in-out));
  }
  100% {
    background-position: -200% 0;
    animation-timing-function: var(--animation--shimmer-burst--easing, var(--easing--ease-in-out));
  }
}
@keyframes spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}
@keyframes skeleton-pulse {
  0%, 100% {
    opacity: var(--animation--skeleton-pulse--opacity-start, 1);
  }
  50% {
    opacity: var(--animation--skeleton-pulse--opacity-end, 0.4);
  }
}
@keyframes opacityPulse {
  0%, 100% {
    opacity: var(--animation--opacity-pulse--opacity-start, 1);
  }
  50% {
    opacity: var(--animation--opacity-pulse--opacity-end, 0.4);
  }
}
@keyframes popoverIn {
  from {
    opacity: 0;
    transform: translate(var(--animation--popover-in--translate-x, 0), var(--animation--popover-in--translate-y, 0)) scale(var(--animation--popover-in--scale, 0.96));
  }
  to {
    opacity: 1;
    transform: translate(0, 0) scale(1);
  }
}
@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(var(--animation--fade-in--translate, 8px));
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes collapsibleSlideDown {
  from {
    height: 0;
  }
  to {
    height: var(--reka-collapsible-content-height);
  }
}
@keyframes collapsibleSlideUp {
  from {
    height: var(--reka-collapsible-content-height);
  }
  to {
    height: 0;
  }
}
/* The filter only exists inside the keyframes: once the animation finishes the
 * element returns to its unfiltered base styles, so no stacking context (or
 * compositing surface) stays active on settled content. */
@keyframes collapsibleSlideDownBlurred {
  from {
    height: 0;
    opacity: 0;
    filter: blur(var(--animation--collapsible-slide-blurred--blur, 4px));
  }
  to {
    height: var(--reka-collapsible-content-height);
    opacity: 1;
    filter: blur(0);
  }
}
@keyframes collapsibleSlideUpBlurred {
  from {
    height: var(--reka-collapsible-content-height);
    opacity: 1;
    filter: blur(0);
  }
  to {
    height: 0;
    opacity: 0;
    filter: blur(var(--animation--collapsible-slide-blurred--blur, 4px));
  }
}
@keyframes blurSwapIn {
  from {
    opacity: 0;
    filter: blur(var(--animation--blur-swap--blur, 4px));
  }
  to {
    opacity: 1;
    filter: blur(0);
  }
}
@keyframes blurSwapOut {
  from {
    opacity: 1;
    filter: blur(0);
  }
  to {
    opacity: 0;
    filter: blur(var(--animation--blur-swap--blur, 4px));
  }
}
