/**
 * Resizer
 */
.vue-flow__resize-control.line {
  border-color: transparent;
  z-index: 1;
}
.vue-flow__resize-control.line.top {
  height: var(--spacing--sm);
  border-top-width: var(--spacing--sm);
}
.vue-flow__resize-control.line.right {
  width: var(--spacing--sm);
  border-right-width: var(--spacing--sm);
}
.vue-flow__resize-control.line.bottom {
  height: var(--spacing--sm);
  border-bottom-width: var(--spacing--sm);
}
.vue-flow__resize-control.line.left {
  width: var(--spacing--sm);
  border-left-width: var(--spacing--sm);
}

.vue-flow__resize-control.handle {
  background-color: transparent;
  width: var(--spacing--sm);
  height: var(--spacing--sm);
  border: 0;
  border-radius: 0;
  z-index: 1;
}

/**
 * Minimap
 */
.vue-flow__minimap {
  height: 120px;
  overflow: hidden;
  margin-bottom: calc(48px + 2 * var(--spacing--xs));
  border: var(--border);
  border-radius: var(--radius);
  background: var(--color--background--light-2);
}
.vue-flow__minimap .minimap-node-default {
  fill: var(--color--foreground--shade-1);
}
.vue-flow__minimap .minimap-node-n8n-nodes-base-stickyNote {
  fill: var(--color--foreground--shade-1);
  opacity: 0.2;
}
@media screen and (max-width: 767px) {
  .vue-flow__minimap {
    display: none;
  }
}

/**
 * Nodes
 */
.vue-flow__node, .vue-flow__node.draggable {
  cursor: pointer;
}
.vue-flow__node.dragging {
  cursor: grabbing;
}
.vue-flow__node:has(.sticky--active) {
  z-index: 1 !important;
}
.vue-flow__node:has(.canvas-handle-plus):hover {
  z-index: 2 !important;
}

.vue-flow__nodes:has(.bring-to-front) {
  z-index: 2 !important;
}

/**
 * Handles
 */
.vue-flow__handle:not(.connectionindicator) .plus {
  display: none;
  position: absolute;
}

/**
 * Selection
 */
.vue-flow__nodesselection-rect {
  box-sizing: content-box;
  margin-top: calc(-1 * var(--spacing--2xs));
  margin-left: calc(-1 * var(--spacing--2xs));
  padding: var(--spacing--2xs);
}

/**
 * Edges
 */
.vue-flow__edges:has(.bring-to-front),
.vue-flow__edge-label.selected {
  z-index: 1 !important;
}

/**
 * Pane
 */
.vue-flow__pane {
  cursor: grab;
}
.vue-flow__pane.selection {
  cursor: default;
}
.vue-flow__pane.dragging {
  cursor: grabbing;
}

/**
 * Controls
 */
.vue-flow__controls {
  margin: var(--spacing--sm);
  display: flex;
  gap: var(--spacing--xs);
  box-shadow: none;
}
@media screen and (max-width: 767px) {
  .vue-flow__controls {
    max-width: calc(100% - 3 * var(--spacing--sm) - var(--spacing--2xs));
    overflow: auto;
    margin-left: 0;
    margin-right: 0;
    padding-left: var(--spacing--sm);
    padding-right: var(--spacing--sm);
  }
}

